{
  "interpretation": {
    "name": "TightenLine2ForkliftFastenersWithSharedNutrunner",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, evaluate and record the result, and return the tool to the crib so that other lines are not blocked.",
    "constraints": [
      "Reserve NR7 exclusively before any use and release it at the end",
      "NR7 must be at st2 (transport-tool to station completed) before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program, with no literal torque, tolerance or bolt count in the Recipe",
      "transport-tool Steps must be delegated to agvexecutor",
      "Every tool-using Step depends on the reserve-tool Step to renew the lease",
      "The tightening must be evaluated and recorded (quality policy)",
      "The tool must be returned to the crib and the reservation released afterwards"
    ],
    "preference": "Release the tool as early as possible so other lines are not blocked, so evaluation and recording run in parallel with the return transport.",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-f30-tightening-with-tool-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "finish",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-bolts"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-bolts",
